const amqp = require('amqplib');
const mongoose = require('mongoose');
const crypto = require('crypto');

const UserSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true },
  passwordHash: { type: String, required: true },
  role: { type: String, enum: ['user', 'admin', 'moderator'], default: 'user' },
  verified: { type: Boolean, default: false },
  apiQuota: { type: Number, default: 100 },
  permissions: { type: [String], default: [] },
  lastLogin: { type: Date },
  profileData: { type: mongoose.Schema.Types.Mixed, default: {} }
});

const User = mongoose.model('User', UserSchema);

const ALLOWED_PROFILE_FIELDS = ['displayName', 'bio', 'avatar', 'timezone', 'locale'];
const INTERNAL_FIELDS = ['role', 'verified', 'apiQuota', 'permissions', 'passwordHash'];

class MessageProcessor {
  constructor(config) {
    this.config = config;
    this.connection = null;
    this.channel = null;
    this.isShuttingDown = false;
    this.activeMessages = new Set();
    this.processingStrategies = new Map();
    this._registerStrategies();
  }

  _registerStrategies() {
    this.processingStrategies.set('profile.update', this._handleProfileUpdate.bind(this));
    this.processingStrategies.set('user.sync', this._handleUserSync.bind(this));
    this.processingStrategies.set('user.onboard', this._handleUserOnboard.bind(this));
  }

  _sanitizeProfilePayload(payload) {
    const sanitized = {};
    for (const key of ALLOWED_PROFILE_FIELDS) {
      if (payload[key] !== undefined) {
        sanitized[key] = String(payload[key]).slice(0, 500);
      }
    }
    return sanitized;
  }

  _buildUpdateQuery(messageType, payload, context) {
    if (messageType === 'profile.update') {
      const profileFields = this._sanitizeProfilePayload(payload.profileData || {});
      return { $set: { profileData: profileFields } };
    }

    if (messageType === 'user.sync') {
      return this._buildSyncQuery(payload, context);
    }

    if (messageType === 'user.onboard') {
      return this._buildOnboardQuery(payload, context);
    }

    return null;
  }

  _buildSyncQuery(payload, context) {
    const update = {};
    const safeFields = ['email', 'lastLogin', 'profileData'];

    for (const field of safeFields) {
      if (payload[field] !== undefined) {
        update[field] = payload[field];
      }
    }

    return { $set: update };
  }

  _buildOnboardQuery(payload, context) {
    const defaults = {
      verified: false,
      apiQuota: 100,
      profileData: {}
    };

    const extracted = this._extractOnboardFields(payload);
    const merged = this._safeMerge(defaults, extracted);
    return { $set: merged };
  }

  _extractOnboardFields(payload) {
    const extracted = {};
    const onboardAllowed = ['profileData', 'locale', 'timezone'];

    for (const key of onboardAllowed) {
      if (payload[key] !== undefined) {
        extracted[key] = payload[key];
      }
    }
    return extracted;
  }

  _safeMerge(target, source) {
    const result = {};
    const allowedKeys = Object.keys(target);

    for (const key of allowedKeys) {
      if (INTERNAL_FIELDS.includes(key) && source[key] !== undefined) {
        result[key] = target[key];
      } else if (source[key] !== undefined && typeof source[key] === 'object' && !Array.isArray(source[key]) && source[key] !== null) {
        result[key] = this._sanitizeNestedObject(source[key]);
      } else if (source[key] !== undefined) {
        result[key] = source[key];
      } else {
        result[key] = target[key];
      }
    }
    return result;
  }

  _sanitizeNestedObject(obj) {
    const sanitized = {};
    for (const key of Object.keys(obj)) {
      if (key.startsWith('$') || key.includes('.')) continue;
      if (INTERNAL_FIELDS.includes(key)) continue;
      const val = obj[key];
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
        sanitized[key] = val;
      }
    }
    return sanitized;
  }

  async _handleProfileUpdate(msg, payload) {
    const { userId } = payload;
    if (!userId || !mongoose.Types.ObjectId.isValid(userId)) {
      throw new Error('Invalid userId');
    }

    const query = this._buildUpdateQuery('profile.update', payload, {});
    await User.updateOne({ _id: userId }, query);
  }

  async _handleUserSync(msg, payload) {
    const { userId, source } = payload;
    if (!userId || !mongoose.Types.ObjectId.isValid(userId)) {
      throw new Error('Invalid userId');
    }

    if (source !== 'identity-provider' && source !== 'admin-panel') {
      throw new Error('Invalid sync source');
    }

    const context = { source, timestamp: Date.now() };
    const query = this._buildUpdateQuery('user.sync', payload, context);
    await User.updateOne({ _id: userId }, query);
  }

  async _handleUserOnboard(msg, payload) {
    const { userId } = payload;
    if (!userId || !mongoose.Types.ObjectId.isValid(userId)) {
      throw new Error('Invalid userId');
    }

    const context = { isOnboarding: true };
    const query = this._buildUpdateQuery('user.onboard', payload, context);
    await User.updateOne({ _id: userId }, query);
  }

  async processMessage(msg) {
    const msgId = msg.properties.messageId || crypto.randomUUID();
    this.activeMessages.add(msgId);

    try {
      const content = JSON.parse(msg.content.toString());
      const { type, payload, metadata } = content;

      if (!type || !payload) {
        this.channel.nack(msg, false, false);
        return;
      }

      const strategy = this.processingStrategies.get(type);
      if (!strategy) {
        this.channel.nack(msg, false, false);
        return;
      }

      await strategy(msg, payload);
      this.channel.ack(msg);
    } catch (err) {
      console.error(`Error processing message ${msgId}:`, err.message);
      this.channel.nack(msg, false, true);
    } finally {
      this.activeMessages.delete(msgId);
    }
  }

  async connect() {
    this.connection = await amqp.connect(this.config.amqpUrl);
    this.channel = await this.connection.createChannel();
    await this.channel.assertQueue(this.config.queue, { durable: true });
    await this.channel.prefetch(this.config.prefetch || 10);

    this.channel.consume(this.config.queue, (msg) => {
      if (this.isShuttingDown) {
        this.channel.nack(msg, false, true);
        return;
      }
      this.processMessage(msg);
    });

    console.log(`Consumer connected to queue: ${this.config.queue}`);
  }

  async shutdown() {
    console.log('Initiating graceful shutdown...');
    this.isShuttingDown = true;

    const maxWait = 30000;
    const start = Date.now();

    while (this.activeMessages.size > 0 && (Date.now() - start) < maxWait) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    if (this.channel) await this.channel.close();
    if (this.connection) await this.connection.close();
    console.log('Shutdown complete.');
  }
}

const processor = new MessageProcessor({
  amqpUrl: process.env.AMQP_URL || 'amqp://localhost',
  queue: 'user-events',
  prefetch: 5
});

process.on('SIGTERM', () => processor.shutdown());
process.on('SIGINT', () => processor.shutdown());

processor.connect().catch(err => {
  console.error('Failed to connect:', err);
  process.exit(1);
});

module.exports = { MessageProcessor, User };
